package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

class TrueTypeFontParseTests {

    @Test
    void parsesTrueTypeTablesAndUsesHeadUnitsPerEm() throws IOException {
        byte[] fontData = createTrueTypeFont();

        TrueTypeFont font = new TrueTypeFont();
        TrueTypeFont result = font.parse(new MemoryTTFDataStream(fontData));

        assertSame(font, result);
        assertEquals(0.00048828125f,
                ((Number) font.getFontMatrix().get(0)).floatValue(),
                0.000000001f);
        assertNotNull(font.getGlyph(0));
        assertEquals(null, font.getGlyph(2));
    }

    @Test
    void rejectsTrueTypeFontWithoutMaxpTable() {
        byte[] fontData = createFontWithHeadOnly();

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> new TrueTypeFont().parse(new MemoryTTFDataStream(fontData)));

        assertNotNull(exception.getMessage());
    }

    private static byte[] createTrueTypeFont() {
        byte[] data = new byte[420];

        writeUInt32(data, 0, 0x00010000L);
        writeUInt16(data, 4, 4);

        writeTableRecord(data, 12, "head", 100, 54);
        writeTableRecord(data, 28, "maxp", 200, 6);
        writeTableRecord(data, 44, "loca", 300, 8);
        writeTableRecord(data, 60, "glyf", 400, 10);

        writeUInt16(data, 118, 2048);
        writeUInt16(data, 150, 1);

        writeUInt16(data, 204, 2);

        writeUInt32(data, 300, 0);
        writeUInt32(data, 304, 10);
        writeUInt32(data, 308, 20);

        return data;
    }

    private static byte[] createFontWithHeadOnly() {
        byte[] data = new byte[128];

        writeUInt32(data, 0, 0x00010000L);
        writeUInt16(data, 4, 1);
        writeTableRecord(data, 12, "head", 64, 54);

        writeUInt16(data, 82, 1000);
        writeUInt16(data, 114, 1);

        return data;
    }

    private static void writeTableRecord(
            byte[] data, int position, String tag, long offset, long length) {
        byte[] tagBytes = tag.getBytes(StandardCharsets.ISO_8859_1);
        System.arraycopy(tagBytes, 0, data, position, 4);
        writeUInt32(data, position + 4, 0);
        writeUInt32(data, position + 8, offset);
        writeUInt32(data, position + 12, length);
    }

    private static void writeUInt16(byte[] data, int position, int value) {
        data[position] = (byte) (value >>> 8);
        data[position + 1] = (byte) value;
    }

    private static void writeUInt32(byte[] data, int position, long value) {
        data[position] = (byte) (value >>> 24);
        data[position + 1] = (byte) (value >>> 16);
        data[position + 2] = (byte) (value >>> 8);
        data[position + 3] = (byte) value;
    }
}

