package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;

public class TrueTypeFontParseTests {

    // Lightweight concrete TTfDataStream to drive parsing paths without a real font file.
    // Implemented with just the minimum surface the tests exercise.
    static class SimpleTTFDataStream extends TTFDataStream {
        private final byte[] data;
        private int pos = 0;

        SimpleTTFDataStream(byte[] data) {
            this.data = data;
        }

        @Override
        public int read() {
            if (pos >= data.length) {
                return -1;
            }
            return data[pos++] & 0xFF;
        }

        @Override
        public long readLong() {
            // not used in tests
            return 0;
        }

        @Override
        public int readUnsignedShort() {
            int a = read();
            int b = read();
            return ((a & 0xFF) << 8) | (b & 0xFF);
        }

        @Override
        public short readSignedShort() {
            int a = read();
            int b = read();
            int v = ((a & 0xFF) << 8) | (b & 0xFF);
            if ((v & 0x8000) != 0) {
                v = v - 0x10000;
            }
            return (short) v;
        }

        @Override
        public void seek(long pos) {
            this.pos = (int) pos;
        }

        @Override
        public java.io.InputStream getOriginalData() {
            return new ByteArrayInputStream(data);
        }

        @Override
        public long getOriginalDataSize() {
            return data.length;
        }

        @Override
        public int read(byte[] b, int off, int len) {
            int remaining = data.length - pos;
            if (remaining <= 0) {
                return -1;
            }
            int toRead = Math.min(len, remaining);
            System.arraycopy(data, pos, b, off, toRead);
            pos += toRead;
            return toRead;
        }

        @Override
        public long getCurrentPosition() {
            return pos;
        }

        @Override
        public void close() throws IOException {
            // no resources to release
        }
    }

    @Test
    public void testType1DetectionPathStopsParsingAndReturnsType1Font() throws IOException {
        // Type1 style header at start (signature 0x80 0x01)
        byte[] ttfHeader = new byte[]{(byte) 0x80, 0x01, 0x00, 0x00};
        SimpleTTFDataStream ds = new SimpleTTFDataStream(ttfHeader);

        TrueTypeFont ttf = new TrueTypeFont();
        ttf.parse(ds);

        try {
            Field f = TrueTypeFont.class.getDeclaredField("type1Font");
            f.setAccessible(true);
            Object v = f.get(ttf);
            assertNotNull(v, "type1Font should be initialized when a Type1 header is detected");
        } catch (NoSuchFieldException | IllegalAccessException e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    @Test
    public void testNonType1PathThrowsIllegalArgumentWhenHeadMissing() throws IOException {
        // Non-Type1 header, followed by insufficient data to form a valid font
        byte[] header = new byte[]{0x00, 0x01, 0x00, 0x00};
        SimpleTTFDataStream ds = new SimpleTTFDataStream(header);

        TrueTypeFont ttf = new TrueTypeFont();
        Exception ex = assertThrows(IllegalArgumentException.class, () -> {
            ttf.parse(ds);
        });

        // Optional: verify message contains a hint about missing required data
        // assertTrue(ex.getMessage().toLowerCase().contains("head"));
    }
}

