        long[] glyphOffsets = (long[]) glyphOffsetsField.get(font);

        assertArrayEquals(new long[]{0L, 4L}, glyphOffsets);
    }

    private static byte[] minimalTrueTypeFontWithLongLocaOffsets() {
        final int headOffset = 76;
        final int maxpOffset = 130;
        final int locaOffset = 136;
        final int glyfOffset = 144;

        ByteBuffer buffer = ByteBuffer.allocate(148).order(ByteOrder.BIG_ENDIAN);

        buffer.putInt(0, 0x00010000);
        buffer.putShort(4, (short) 4);
        buffer.putShort(6, (short) 0);
        buffer.putShort(8, (short) 0);
        buffer.putShort(10, (short) 0);

        putTableRecord(buffer, 12, "head", headOffset, 54);
        putTableRecord(buffer, 28, "maxp", maxpOffset, 6);
        putTableRecord(buffer, 44, "loca", locaOffset, 8);
        putTableRecord(buffer, 60, "glyf", glyfOffset, 4);

        buffer.putShort(headOffset + 18, (short) 1000);
        buffer.putShort(headOffset + 50, (short) 1);

        buffer.putInt(maxpOffset, 0x00010000);
        buffer.putShort(maxpOffset + 4, (short) 1);

        buffer.putInt(locaOffset, 0);
        buffer.putInt(locaOffset + 4, 4);

        return buffer.array();
    }

    private static void putTableRecord(
            ByteBuffer buffer, int position, String tag, int offset, int length) {
        buffer.position(position);
        buffer.put(tag.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
        buffer.putInt(0);
        buffer.putInt(offset);
        buffer.putInt(length);
    }
}

