import static org.junit.jupiter.api.Assertions.assertSame;

class PointUtilCalPdfPathPointTests {

    @Test
    void scalesArcEndpointButDoesNotScaleRadiusOutsideLegacyMode() {
        PathPoint arc = new PathPoint(
                "A",
                3.0f, 4.0f,
                15.0f, 1.0f, 0.0f,
                3.0f, 5.0f
        );
        PathPoint ignored = new PathPoint("Z", 0, 0, 0, 0, 0, 0);

        List<PathPoint> result = PointUtil.calPdfPathPoint(
                100.0,
                100.0,
                null,
                Arrays.asList(arc, ignored),
                true,
                ST_Array.unitCTM(),
                null,
                null,
                false,
                2.0
        );

        assertEquals(1, result.size());
        PathPoint converted = result.get(0);

