package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.ofdrw.converter.point.TextCodePoint;
import org.ofdrw.core.basicType.ST_Array;
import org.ofdrw.core.text.CT_CGTransform;
import org.ofdrw.core.text.TextCode;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class PointUtilCalPdfTextCoordinateTests {

    @Test
    void skipsInsufficientGlyphPositionEvenWhenCtmIsEnabled() {
        TextCode textCode = new TextCode()
                .setContent("abc")
                .setCoordinate(10d, 20d)
                .setDeltaX(new ST_Array("5", "7"));

        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(1)
                .setGlyphs(new ST_Array("glyph-a"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                200,
                300,
                null,
                12,
                Collections.singletonList(textCode),
                Collections.singletonList(transform),
                null,
                null,
                true,
                new ST_Array(1, 0, 0, 1, 100, 50),
                false,
                1
        );

        assertEquals(3, points.size());
        assertEquals("a", property(points.get(0), "text"));
        assertEquals("", property(points.get(1), "text"));
        assertEquals("c", property(points.get(2), "text"));

        double firstX = numericProperty(points.get(0), "x");
        double skippedX = numericProperty(points.get(1), "x");
        double thirdX = numericProperty(points.get(2), "x");

        assertEquals(firstX, skippedX, 1.0e-9);
        assertEquals(5.0, thirdX - skippedX, 1.0e-9);
        assertEquals("glyph-a", property(points.get(0), "glyph"));
    }

    private static String property(Object target, String name) {
        Object value = readProperty(target, name);
        return value == null ? null : value.toString();
    }

    private static double numericProperty(Object target, String name) {
        Object value = readProperty(target, name);
        assertNotNull(value);
        return ((Number) value).doubleValue();
    }

    private static Object readProperty(Object target, String name) {
        String suffix = Character.toUpperCase(name.charAt(0)) + name.substring(1);
        try {
            Method method = target.getClass().getMethod("get" + suffix);
            return method.invoke(target);
        } catch (ReflectiveOperationException ignored) {
            Class<?> type = target.getClass();
            while (type != null) {
                try {
                    Field field = type.getDeclaredField(name);
                    field.setAccessible(true);
                    return field.get(target);
                } catch (ReflectiveOperationException ignoredField) {
                    type = type.getSuperclass();
                }
            }
            throw new AssertionError("No readable property named " + name);
        }
    }
}

