package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class NamedColorRgbTests {

    @Test
    void returnsNullForNullAndUnrecognizedColors() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb("not-a-color"));
    }

    @Test
    void resolvesNamedColorsCaseInsensitivelyAndTrimsWhitespace() {
        assertArrayEquals(new int[]{255, 0, 0}, NamedColor.rgb("  ReD  "));
    }

    @Test
    void expandsThreeDigitHexadecimalColors() {
        assertArrayEquals(new int[]{0, 255, 136}, NamedColor.rgb("#0f8"));
    }

    @Test
    void parsesRgbComponentsAfterTrimmingEachValue() {
        assertArrayEquals(
                new int[]{12, 34, 56},
                NamedColor.rgb(" RGB( 12, 34, 56 ) ")
        );
    }

    @Test
    void parsesTheFourthRgbaValueAsAlpha() {
        assertArrayEquals(
                new int[]{10, 20, 30, 127},
                NamedColor.rgb("rgba(10, 20, 30, 0.5, 0.1)")
        );
    }
}

