package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

class NamedColorRgbTests {

    @Test
    void resolvesTrimmedCaseInsensitiveNamedColor() {
        int[] result = NamedColor.rgb("  LiGhTSeAgReEn ");

        assertArrayEquals(new int[]{32, 178, 170}, result);
    }

    @Test
    void expandsThreeDigitHexadecimalColor() {
        int[] result = NamedColor.rgb(" #0af ");

        assertArrayEquals(new int[]{0, 170, 255}, result);
    }

    @Test
    void parsesRgbComponentsWithWhitespace() {
        int[] result = NamedColor.rgb(" RGB( 12, 34, 56 ) ");

        assertArrayEquals(new int[]{12, 34, 56}, result);
    }

    @Test
    void parsesTheFourthRgbaValueAsAlpha() {
        int[] result = NamedColor.rgb("rgba(10, 20, 30, 0.5, 0.25)");

        assertArrayEquals(new int[]{10, 20, 30, 127}, result);
    }

    @Test
    void decodesSixDigitHexadecimalColor() {
        int[] result = NamedColor.rgb("#3366cc");

        assertArrayEquals(new int[]{51, 102, 204}, result);
    }

    @Test
    void returnsNullForNullEmptyAndUndecodableInputs() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
        assertNull(NamedColor.rgb("not-a-color"));
    }

    @Test
    void whitespaceOnlyInputIsNotTreatedAsAValidColor() {
        assertThrows(RuntimeException.class, () -> NamedColor.rgb("   "));
    }
}

