import static org.junit.jupiter.api.Assertions.assertTrue;

class DivRenderRenderTests {

    @Test
    void rendersUnequalBordersWithTheConfiguredRightBorderWidth() {
        Div<?> div = new Div(10d, 20d, 30d, 40d)
                .setBorder(1d, 7d, 3d, 4d);

        CT_PageBlock layer = new CT_PageBlock();
        AtomicInteger maxUnitId = new AtomicInteger(100);

        DivRender.render(layer, div, maxUnitId);

        List<PageBlockType> pageBlocks = layer.getPageBlocks();

        assertEquals(4, pageBlocks.size());
        assertEquals(104, maxUnitId.get());

        PathObject rightBorder = (PathObject) pageBlocks.get(3);
        assertEquals(104, rightBorder.getID().getId());
        assertEquals(7d, rightBorder.getLineWidth());

        assertEquals(47d, coordinate(rightBorder.getBoundary(), "x", "getX", "getLeft"));
        assertEquals(21d, coordinate(rightBorder.getBoundary(), "y", "getY", "getBottom"));
        assertEquals(7d, rightBorder.getBoundary().getWidth());
        assertEquals(40d, rightBorder.getBoundary().getHeight());
    }

    @Test
    void skipsBorderlessDivWithoutCheckingItsHeight() {
        CT_PageBlock layer = new CT_PageBlock();
        AtomicInteger maxUnitId = new AtomicInteger(25);

        DivRender.render(layer, new Div<>(), maxUnitId);

        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(25, maxUnitId.get());
    }

    private static double coordinate(Object box, String fieldName, String... methodNames) {
        try {
            Field field = box.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return ((Number) field.get(box)).doubleValue();
        } catch (ReflectiveOperationException ignored) {
            for (String methodName : methodNames) {
                try {
                    Method method = box.getClass().getMethod(methodName);
                    return ((Number) method.invoke(box)).doubleValue();
                } catch (ReflectiveOperationException ignoredMethod) {
                    // Try the next supported representation.
                }
            }
        }

        throw new AssertionError("Unable to read boundary coordinate: " + fieldName);
    }
}

