/**
 * Tests for ParagraphRender.render(..) focusing on edge/input boundary behaviors as described
 * in the specification. The tests aim to differentiate behavior by asserting no side effects
 * when given null or empty inputs.
 */
public class ParagraphRenderRenderTests {

    /**
     * When the paragraph is null, render should return immediately without throwing any exception.
     */
    @Test
    public void render_NullParagraph_ReturnsImmediately() {
        CT_PageBlock layer = new CT_PageBlock();
        // maxUnitID starts at 0
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Should not throw
        assertDoesNotThrow(() -> ParagraphRender.render(layer, null, null, maxUnitID));

        // No side effects on layer or maxUnitID
        assertEquals(0, maxUnitID.get(), "maxUnitID should remain unchanged when paragraph is null");
        assertEquals(0, layer.getPageBlocks().size(), "Layer should remain empty when paragraph is null");
    }

    /**
     * When the paragraph has no content (lines), rendering should not add any blocks to the layer.
     */
    @Test
    public void render_EmptyParagraph_DoesNotModifyLayer() {
        CT_PageBlock layer = new CT_PageBlock();
        Paragraph emptyParagraph = new Paragraph();
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Should not throw and should not modify layer
        ParagraphRender.render(layer, null, emptyParagraph, maxUnitID);

        assertEquals(0, layer.getPageBlocks().size(), "Layer should contain no blocks after rendering an empty paragraph");
        assertEquals(0, maxUnitID.get(), "maxUnitID should not be incremented for an empty render");
    }
}

