                Side.Right,
                7.0,
                20.0,
                10.0,
                2.0,
                Arrays.asList(firstCut, secondCut)
        );

        AtomicInteger nextId = new AtomicInteger();
        SignIDProvider ids = new SignIDProvider() {
            @Override
            public void setCurrentMaxSignId(String maxSignId) {
                nextId.set(Integer.parseInt(maxSignId.substring(1)));
            }

            @Override
            public String incrementAndGet() {
                return "s" + nextId.incrementAndGet();
            }

            @Override
            public String get() {
                return "s" + nextId.get();
            }

            @Override
            public int parse(String id) {
                return Integer.parseInt(id.substring(1));
            }
        };

        List<StampAnnot> appearances = position.getAppearance(reader, ids);

        assertEquals(4, appearances.size());
        assertEquals("s1", appearances.get(0).getID());
        assertEquals("s2", appearances.get(1).getID());
        assertEquals("s3", appearances.get(2).getID());
        assertEquals("s4", appearances.get(3).getID());

        assertEquals(4.0, appearances.get(0).getClip().getWidth(), 1e-9);
        assertEquals(6.0, appearances.get(1).getClip().getWidth(), 1e-9);

        // The second annotation on page two represents the right portion
        // of the first adjacent cut, not the left portion of the next cut.
        assertEquals(16.0, appearances.get(2).getClip().getWidth(), 1e-9);
        assertEquals(14.0, appearances.get(3).getClip().getWidth(), 1e-9);

        assertEquals(7.0, appearances.get(1).getBoundary().getTopLeftY(), 1e-9);
        assertEquals(20.0, appearances.get(1).getBoundary().getWidth(), 1e-9);
        assertEquals(10.0, appearances.get(1).getBoundary().getHeight(), 1e-9);
        assertNotSame(appearances, position.getAppearance(reader, ids));
    }

