import static org.junit.jupiter.api.Assertions.assertEquals;

class CuttingRideStampPosGetAppearanceTests {

    @Test
    void leftSideUsesConfiguredOffsetWhenCuttingRatiosArePresent() throws Exception {
        Path root = createTwoPageOfd();

        try {
            OFDReader reader = new OFDReader(root.toString(), false);

            CuttingRatio ratio = new CuttingRatio();
            ratio.setLeft(0.25);
            ratio.setRight(0.75);

            CuttingRideStampPos position = new CuttingRideStampPos(
                    Side.Left,
                    7.0,
                    40.0,
                    20.0,
                    3.0,
                    Arrays.asList(ratio)
            );

            List<StampAnnot> appearances =
                    position.getAppearance(reader, new SequentialSignIdProvider());

            assertEquals(2, appearances.size());
            assertEquals("s001", appearances.get(0).getID());
            assertEquals("s002", appearances.get(1).getID());

            assertEquals(7.0, appearances.get(0).getBoundary().getTopLeftY(), 0.000001);
            assertEquals(7.0, appearances.get(1).getBoundary().getTopLeftY(), 0.000001);

            assertEquals(10.0, appearances.get(0).getClip().getWidth(), 0.000001);
            assertEquals(30.0, appearances.get(1).getClip().getWidth(), 0.000001);

            assertEquals(177.0, appearances.get(0).getBoundary().getTopLeftX(), 0.000001);
            assertEquals(-7.0, appearances.get(1).getBoundary().getTopLeftX(), 0.000001);
        } finally {
            deleteRecursively(root);
        }
    }

    private static Path createTwoPageOfd() throws IOException {
        Path root = Files.createTempDirectory("cutting-ride-stamp-test");
        Path doc = root.resolve("Doc_0");
        Path pages = doc.resolve("Pages");

        Files.createDirectories(pages.resolve("Page_1"));
        Files.createDirectories(pages.resolve("Page_2"));

        Files.write(
                root.resolve("OFD.xml"),
                (
                        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
                                + "<OFD Version=\"1.1\" DocType=\"OFD\" "
                                + "xmlns=\"http://www.ofdspec.org/2016\">"
                                + "<DocBody><DocRoot>Doc_0/Document.xml</DocRoot></DocBody>"
                                + "</OFD>"
                ).getBytes(StandardCharsets.UTF_8)
        );

        Files.write(
                doc.resolve("Document.xml"),
                (
                        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
                                + "<Document xmlns=\"http://www.ofdspec.org/2016\">"
                                + "<CommonData MaxUnitID=\"2\">"
                                + "<PageArea><PhysicalBox>0 0 200 100</PhysicalBox></PageArea>"
                                + "</CommonData>"
                                + "<Pages>"
                                + "<Page ID=\"1\" BaseLoc=\"Pages/Page_1/Content.xml\"/>"
                                + "<Page ID=\"2\" BaseLoc=\"Pages/Page_2/Content.xml\"/>"
                                + "</Pages>"
                                + "</Document>"
                ).getBytes(StandardCharsets.UTF_8)
        );

        String pageTemplate = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
                + "<Page xmlns=\"http://www.ofdspec.org/2016\" ID=\"%d\">"
                + "<Area><PhysicalBox>0 0 200 100</PhysicalBox></Area>"
                + "</Page>";

        Files.write(
                pages.resolve("Page_1").resolve("Content.xml"),
                String.format(pageTemplate, 1).getBytes(StandardCharsets.UTF_8)
        );
        Files.write(
                pages.resolve("Page_2").resolve("Content.xml"),
                String.format(pageTemplate, 2).getBytes(StandardCharsets.UTF_8)
        );

        return root;
    }

    private static void deleteRecursively(Path root) throws IOException {
        if (root != null && Files.exists(root)) {
            try (Stream<Path> paths = Files.walk(root)) {
                paths.sorted(Comparator.reverseOrder()).forEach(path -> {
                    try {
                        Files.deleteIfExists(path);
                    } catch (IOException exception) {
                        throw new RuntimeException(exception);
                    }
                });
            }
        }
    }

    private static final class SequentialSignIdProvider implements SignIDProvider {
        private int next = 1;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            next = Integer.parseInt(maxSignId.substring(1)) + 1;
        }

        @Override
        public String incrementAndGet() {
            return String.format("s%03d", next++);
        }

        @Override
        public String get() {
            return String.format("s%03d", next - 1);
        }

        @Override
        public int parse(String id) {
            return Integer.parseInt(id.substring(1));
        }
    }
}

