        when(ctx.getPage(Mockito.anyInt())).thenReturn(null);
        when(ctx.getPageSize(Mockito.any())).thenReturn(pageSize);
        ST_RefID ref = ST_RefID.getInstance("Ref");
        when(ctx.getPageObjectId(anyInt())).thenReturn(new PageObjIdHolder(ref));

        // Use null side to trigger bottom/top branch without requiring an actual Side enum
        RidingStampPos pos = new RidingStampPos((RidingStampPos.Side) null, (Double) null, 100.0, 60.0);
        SignIDProvider idProvider = Mockito.mock(SignIDProvider.class);
        when(idProvider.incrementAndGet()).thenReturn("s001").thenReturn("s002").thenReturn("s003").thenReturn("s004");

        List<StampAnnot> anns = pos.getAppearance(ctx, idProvider);
        assertEquals(4, anns.size(), "Should create 4 annotations for 4 pages");

        // All X should be centered: page width 800, stamp width 100 -> (800/2 - 50) = 350
        for (StampAnnot a : anns) {
            Double x = getBoundaryX(a.getBoundary());
            if (x != null) {
                assertEquals(350.0, x, 0.0001, "X should be centered when offset is null");
            }
        }
    }

    /**
     * Verifies that nulls and other non-Right/Left/Bottom sides take top-side branch.
     * For Top (treated as top), Y is calculated accordingly.
     */
    @Test
    void testTopSide_TreatedAsTopBranch() {
        OFDReader ctx = Mockito.mock(OFDReader.class);
        when(ctx.getNumberOfPages()).thenReturn(2);
        ST_Box pageSize = new ST_Box(600.0, 900.0, 0, 0);
        when(ctx.getPage(Mockito.anyInt())).thenReturn(null);
        when(ctx.getPageSize(Mockito.any())).thenReturn(pageSize);
        ST_RefID ref = ST_RefID.getInstance("Ref");
        when(ctx.getPageObjectId(anyInt())).thenReturn(new PageObjIdHolder(ref));

        // Pass null side to trigger top-side branch
        RidingStampPos pos = new RidingStampPos((RidingStampPos.Side) null, (Double) null, 100.0, 100.0);
        SignIDProvider idProvider = Mockito.mock(SignIDProvider.class);
        when(idProvider.incrementAndGet()).thenReturn("s001").thenReturn("s002");

        List<StampAnnot> anns = pos.getAppearance(ctx, idProvider);
        assertEquals(2, anns.size(), "Should create 2 annotations for 2 pages");
        // For top branch with offset null, X should be centered and Y should progress from 0 decreasing with i
        for (StampAnnot a : anns) {
            // boundary width/height are as configured
            assertEquals(100.0, a.getBoundary().getWidth(), 0.0001);
            assertEquals(100.0, a.getBoundary().getHeight(), 0.0001);
        }
    }

    /**
     * Minimal holder to satisfy getPageObjectId(int).ref() chaining in mocks.
     */
    private static class PageObjIdHolder {
        private final ST_RefID ref;

        PageObjIdHolder(ST_RefID ref) {
            this.ref = ref;
        }

        public ST_RefID ref() {
            return ref;
        }
    }

    /**
     * Try to read a possible X coordinate from ST_Box using reflection in case the API does not expose getX().
     * Returns null if no such accessor exists or access fails.
     */
    private Double getBoundaryX(ST_Box boundary) {
        if (boundary == null) {
            return null;
        }
        try {
            // Try common method names
            for (String methodName : new String[]{"getX", "getLeft", "getX1", "getX2", "getPositionX"}) {
                try {
                    Method m = boundary.getClass().getMethod(methodName);
                    Object val = m.invoke(boundary);
                    if (val instanceof Number) {
                        return ((Number) val).doubleValue();
                    }
                } catch (NoSuchMethodException ignored) {
                    // try next
                } catch (Exception e) {
                    // ignore other reflection issues
                }
            }
        } catch (Exception ignored) {
        }
        return null;
    }
}

